export const barrel = (g, x, y, z, facing = "up") => g.set(x, y, z, "barrel", { facing, open: "false" });
export const chest = (g, x, y, z, facing = "north") => g.set(x, y, z, "chest", { facing, type: "single", waterlogged: "false" });
