export function roseArch(g, { x, zA, zB, y = 1 }) {
  for (const z of [zA, zB]) {
    for (let k = 0; k < 3; k++) g.set(x, y + k, z, ...B.fence("spruce"));
    for (const dx of [-1, 1]) {
