/** The well: 3x3 stone-brick ring around a water source, four dark-oak posts, a crossbeam with a chain and bucket, a pyramid roof. */
export function well(g, { cx, cz, y = 1 }) {
  for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) {
